#include "ast.h"
#include <stdlib.h>
AstNode *ast_new(AstNodeType type,size_t line,size_t column){AstNode*n=calloc(1,sizeof(*n));if(!n)return NULL;n->type=type;n->line=line;n->column=column;return n;}
bool ast_list_push(AstNodeList*l,AstNode*n){if(l->count==l->capacity){size_t c=l->capacity?l->capacity*2U:4U;AstNode**p=realloc(l->items,c*sizeof(*p));if(!p)return false;l->items=p;l->capacity=c;}l->items[l->count++]=n;return true;}
static void free_list(AstNodeList*l){for(size_t i=0;i<l->count;i++)ast_free(l->items[i]);free(l->items);}
void ast_free(AstNode*n){if(!n)return;switch(n->type){case AST_STRING:free(n->as.string);break;case AST_IDENTIFIER:free(n->as.identifier);break;case AST_LIST:free_list(&n->as.list.elements);break;case AST_UNARY:ast_free(n->as.unary.operand);break;case AST_BINARY:ast_free(n->as.binary.left);ast_free(n->as.binary.right);break;case AST_CALL:ast_free(n->as.call.callee);free_list(&n->as.call.arguments);break;case AST_LET:free(n->as.declaration.name);ast_free(n->as.declaration.value);break;case AST_ASSIGNMENT:free(n->as.assignment.name);ast_free(n->as.assignment.value);break;case AST_EXPRESSION_STATEMENT:ast_free(n->as.expression_statement.expression);break;case AST_RETURN:ast_free(n->as.return_statement.value);break;case AST_IF:ast_free(n->as.if_statement.condition);ast_free(n->as.if_statement.then_branch);ast_free(n->as.if_statement.else_branch);break;case AST_PROGRAM:case AST_BLOCK:free_list(&n->as.block.statements);break;default:break;}free(n);}
